        {fn && <polyline className="trm-nm-conn" key={"cn" + si} pathLength="1" points={`${X(fn.at) + 14},${Y(fn.at)} ${(X(fn.at) + docL) / 2 + 20},${Y(fn.at)} ${(X(fn.at) + docL) / 2 + 20},${docY} ${docL - 2},${docY}`} />}
