      const from = target != null ? target : sc.scrollTop;
      let i = 0; P.forEach((y, k) => { if (Math.abs(y - from) < Math.abs(P[i] - from)) i = k; });
      const j = Math.max(0, Math.min(P.length - 1, i + dir));
